actions.script:
def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
allowed = false
if (activeOrg && activeOrg != '_NA_') {
    allowed = ec.entity.find(entityName).condition(idField, idValue).disableAuthz().list()
            .any { it.get(orgField) == activeOrg }
}

def editable = ['statusId','firstName','lastName','companyName','designation','email','phone','mobile',
    'website','address','city','regionCode','postalCode','taxRegistrationNumber','taxIdNumber',
    'leadSourceId','rating','estimatedAmount','estimatedCloseDate','description','lostReason']
leadUpdate = [leadId:leadId]
editable.each { key -> if (context.containsKey(key)) leadUpdate[key] = context[key] }
if (leadUpdate.containsKey('firstName')) leadUpdate.firstName = leadUpdate.firstName?.trim()
if (leadUpdate.containsKey('email')) leadUpdate.email = leadUpdate.email?.trim()?.toLowerCase(java.util.Locale.ROOT)
if (leadUpdate.containsKey('mobile')) leadUpdate.mobile = leadUpdate.mobile?.trim()

import org.slf4j.LoggerFactory def logger = LoggerFactory.getLogger("GdprServices")
String scrambledHash = "ANON_" + java.util.UUID.randomUUID().toString().substring(0, 8).toUpperCase()
if (person) { person.firstName = scrambledHash person.lastName = "Redacted" person.birthDate = null person.maritalStatusEnumId = null person.employmentStatusEnumId = null person.update() logger.info("GDPR: Person Name/DOB anonymized for Party [${partyId}]") }
